<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import SmisTopBar from '@/components/SmisTopBar.vue'
import SmisStatusTag from '@/components/SmisStatusTag.vue'
import SmisIcon from '@/components/SmisIcon.vue'
import { useAuthStore } from '@/stores/auth'
import { getHazard, submitHazardAcceptance, submitHazardRectification } from '@/api/smis'
import { getErrorMessage, uploadFile } from '@/api/supabase'
import type { HazardDetail } from '@/api/types'
import { formatDate, hazardLevelBadge } from '@/utils/format'
const auth=useAuthStore();const detail=ref<HazardDetail|null>(null);const loading=ref(true);const saving=ref(false);const uploading=ref(false);const action=reactive({description:'',imageUrls:[] as string[]})
const actionTitle=computed(()=>detail.value?.status==='rectifying'?'提交整改':detail.value?.status==='pending_acceptance'?'验收处理':'')
async function load(id:string){if(!(await auth.ensureValidSession()))return;loading.value=true;try{detail.value=await getHazard(auth.token,id)}catch(e){uni.showToast({title:getErrorMessage(e),icon:'none'})}finally{loading.value=false}}
function addPhotos(){uni.chooseImage({count:6-action.imageUrls.length,sizeType:['compressed'],sourceType:['camera','album'],async success(r){uploading.value=true;try{for(const path of r.tempFilePaths)action.imageUrls.push(await uploadFile(path,auth.token,'smis/hazard-action'))}catch(e){uni.showToast({title:getErrorMessage(e),icon:'none'})}finally{uploading.value=false}}})}
function preview(url:string){if(detail.value)uni.previewImage({urls:detail.value.imageUrls,current:url})}
async function submit(result?:'passed'|'rejected'){if(!detail.value)return;if(!action.description.trim())return uni.showToast({title:'请填写处理说明',icon:'none'});if(!action.imageUrls.length)return uni.showToast({title:'请上传现场证据',icon:'none'});saving.value=true;try{if(detail.value.status==='rectifying')await submitHazardRectification(auth.token,detail.value.id,{completedAt:new Date().toISOString(),description:action.description.trim(),imageUrls:action.imageUrls});else await submitHazardAcceptance(auth.token,detail.value.id,{result:result||'passed',description:action.description.trim(),imageUrls:action.imageUrls});uni.showToast({title:result==='rejected'?'已退回整改':'处理已提交',icon:'success'});action.description='';action.imageUrls=[];await load(detail.value.id)}catch(e){uni.showToast({title:getErrorMessage(e,'处理失败'),icon:'none'})}finally{saving.value=false}}
onLoad(q=>load(String(q?.id||'')))
</script>
<template><view class="page-shell"><SmisTopBar :title="detail?.hazardNo||'隐患详情'" subtitle="隐患治理闭环" show-back/><view class="page-body detail-body"><view v-if="loading" class="loading"><wd-loading color="#4f46e5"/></view><template v-else-if="detail"><view class="hazard-main surface-card"><view class="hazard-main__head"><view class="level">{{hazardLevelBadge(detail.hazardLevel)}}</view><view><SmisStatusTag :status="detail.status"/><text>{{detail.inspectionTypeName||'现场隐患'}}</text></view></view><text class="hazard-main__desc">{{detail.description}}</text><view class="hazard-main__place"><SmisIcon name="location" size="30rpx"/><text>{{detail.location}}</text></view><scroll-view v-if="detail.imageUrls.length" class="photos" scroll-x><image v-for="url in detail.imageUrls" :key="url" :src="url" mode="aspectFill" role="button" aria-label="预览隐患现场照片" @tap="preview(url)"/></scroll-view></view><view class="facts surface-card"><text class="title">隐患信息</text><view><text>上报人</text><text class="strong">{{detail.reporterEmployeeName}}</text></view><view><text>上报时间</text><text class="strong">{{formatDate(detail.reportedAt,true)}}</text></view><view><text>整改责任人</text><text class="strong">{{detail.rectificationResponsibleEmployeeName||'待核准指定'}}</text></view><view><text>整改期限</text><text class="strong">{{formatDate(detail.rectificationDeadline)}}</text></view><view v-if="detail.rectificationSuggestion"><text>整改建议</text><text class="strong">{{detail.rectificationSuggestion}}</text></view></view><view class="timeline"><text class="title">闭环轨迹</text><view v-for="(event,index) in detail.events" :key="event.id" class="event"><view class="event__rail"><view class="i" :class="{'event__dot--current':index===0}"/><view class="span" v-if="index<detail.events.length-1"/></view><view class="event__copy"><view><text class="strong">{{event.eventTitle}}</text><text class="small">{{formatDate(event.eventAt,true)}}</text></view><text>{{event.eventContent||event.operatorEmployeeName||'节点已记录'}}</text></view></view></view><view v-if="actionTitle" class="action surface-card"><text class="title">{{actionTitle}}</text><textarea v-model="action.description" name="hazard-action-description" aria-label="整改或验收说明" auto-height maxlength="500" :placeholder="detail.status==='rectifying'?'说明整改措施与完成情况':'填写验收意见'"/><view class="action__photos"><view v-for="(url,index) in action.imageUrls" :key="url" class="action__photo"><image :src="url" mode="aspectFill"/><button aria-label="移除整改证据照片" @tap="action.imageUrls.splice(index,1)"><SmisIcon name="close" size="24rpx"/></button></view><button v-if="action.imageUrls.length<6" :disabled="uploading" @tap="addPhotos"><wd-loading v-if="uploading" color="#4f46e5"/><SmisIcon v-else name="camera" size="36rpx"/><text>上传证据</text></button></view><button v-if="detail.status==='rectifying'" class="primary" :disabled="saving" @tap="submit()">提交整改，等待验收</button><view v-else class="accept-actions"><button :disabled="saving" @tap="submit('rejected')">退回整改</button><button :disabled="saving" @tap="submit('passed')">验收通过</button></view></view></template><view v-else class="loading">隐患不存在或无权查看</view></view></view></template>
<style scoped lang="scss">.detail-body{padding-bottom:50rpx}.loading{min-height:340rpx;display:flex;align-items:center;justify-content:center;color:var(--smis-text-muted)}.hazard-main{margin-top:-40rpx;padding:26rpx}.hazard-main__head{display:flex;align-items:center;gap:15rpx}.level{width:64rpx;height:64rpx;border-radius:19rpx;background:#fff1df;color:var(--smis-warning);font-size:28rpx;font-weight:700;display:flex;align-items:center;justify-content:center}.hazard-main__head>view:nth-child(2){display:flex;flex-direction:column;align-items:flex-start;gap:7rpx}.hazard-main__head>view>text{font-size:20rpx;color:var(--smis-text-muted)}.hazard-main__desc{display:block;margin-top:20rpx;font-size:29rpx;font-weight:700;line-height:1.55}.hazard-main__place{margin-top:16rpx;padding:15rpx;border-radius:15rpx;background:#f4f7f9;color:var(--smis-text-secondary);font-size:22rpx;display:flex;align-items:flex-start;gap:8rpx}.photos{width:100%;white-space:nowrap;margin-top:18rpx}.photos image{display:inline-block;width:220rpx;height:160rpx;margin-right:12rpx;border-radius:16rpx}.facts{margin-top:17rpx;padding:25rpx}.title{display:block;margin-bottom:17rpx;font-size:28rpx;font-weight:700}.facts>view{min-height:70rpx;display:grid;grid-template-columns:150rpx 1fr;gap:16rpx;align-items:center}.facts>view+view{border-top:1rpx solid var(--smis-line)}.facts>view text{color:var(--smis-text-muted);font-size:20rpx}.facts .strong{font-size:22rpx;line-height:1.5}.timeline{margin-top:27rpx;padding:0 6rpx}.event{display:flex;gap:16rpx}.event__rail{width:24rpx;display:flex;flex-direction:column;align-items:center}.event__rail .i{width:18rpx;height:18rpx;border:4rpx solid #9eb1bf;border-radius:50%;background:var(--smis-bg)}.event__rail .event__dot--current{border-color:var(--smis-safety)}.event__rail .span{width:2rpx;min-height:76rpx;flex:1;background:#d8e1e7}.event__copy{min-width:0;flex:1;padding:0 0 28rpx}.event__copy>view{display:flex;justify-content:space-between;gap:12rpx}.event__copy .strong{font-size:23rpx}.event__copy .small{color:var(--smis-text-muted);font-size:18rpx}.event__copy>text{display:block;margin-top:7rpx;color:var(--smis-text-secondary);font-size:20rpx;line-height:1.45}.action{margin-top:20rpx;padding:25rpx}.action textarea{width:100%;min-height:130rpx;padding:18rpx;border-radius:16rpx;background:#f4f7f9;font-size:23rpx;line-height:1.5}.action__photos{margin-top:14rpx;display:grid;grid-template-columns:repeat(3,1fr);gap:11rpx}.action__photo,.action__photos>button{position:relative;width:100%;height:170rpx;border-radius:15rpx;overflow:hidden}.action__photo image{width:100%;height:100%}.action__photo button{position:absolute;right:6rpx;top:6rpx;width:46rpx;height:46rpx;margin:0;padding:0;border-radius:50%;background:rgba(0,0,0,.65);color:#fff;display:flex;align-items:center;justify-content:center}.action__photos>button{margin:0;border:2rpx dashed #bbc9d2;background:#f5f8fa;color:var(--smis-primary);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:7rpx;font-size:19rpx}.primary,.accept-actions button{min-height:88rpx;margin-top:20rpx;border-radius:17rpx;font-size:24rpx;font-weight:700}.primary{width:100%;background:var(--smis-hero-gradient);color:#fff}.accept-actions{display:grid;grid-template-columns:1fr 1.5fr;gap:12rpx}.accept-actions button{margin-left:0;margin-right:0;background:#edf2f5;color:var(--smis-warning)}.accept-actions button:last-child{background:var(--smis-success);color:#fff}</style>
